# -- Expand Query --


def expand_query(
    query: str,
    api_key: <REDACTED> | None = None,
) -> list[str]:
    """Expand a search query into related queries."""
    key = require_api_key(api_key)
    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
        **_auth_headers(key),
    }

    with _client() as client:
        resp = _request_with_retry(
            "POST", f"{SEARCH_SVIP_BASE}/",
            client, headers=headers,
            json={"q": query, "query_expansion": True},
        )
    data = resp.json()
    return data.get("results", data.get("data", []))


# -- Embeddings API --


def embed(
    texts: list[str],
    api_key: <REDACTED> | None = None,
    model: str = "jina-embeddings-v5-text-small",
    task: str = "text-matching",
    dimensions: int | None = None,
    late_chunking: bool = False,
) -> list[dict]:
    """Generate embeddings for texts."""
    key = require_api_key(api_key)
    headers = {
        "Content-Type": "application/json",
        **_auth_headers(key),
    }

    body: dict = {
        "model": model,
        "task": task,
        "input": texts,
    }
    if dimensions:
        body["dimensions"] = dimensions
    if late_chunking:
        body["late_chunking"] = True

    with _client() as client:
        resp = _request_with_retry(
            "POST", f"{API_BASE}/v1/embeddings",
            client, headers=headers, json=body,
        )
    data = resp.json()
    return data.get("data", [])


